def step(pos, vel, dt, masses):
    # Simple symplectic Euler
    n = len(masses)
    acc = np.zeros_like(pos)

    for i in range(n):
        for j in range(n):
            if i != j:
                r_vec = pos[j] - pos[i]
                r = np.linalg.norm(r_vec)
                acc[i] += masses[j] * r_vec / r**3

    vel += acc * dt
    pos += vel * dt
    return pos, vel
